\set ON_ERROR_STOP on
-- Runs against the disposable fixture only; production data is never loaded.
create function pg_temp.assert(ok boolean, message text) returns void language plpgsql as $$ begin if ok is not true then raise exception 'Assertion failed: %',message; end if; end $$;
insert into teams(id,coach_id) values ('10000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000001'),('10000000-0000-0000-0000-000000000002','00000000-0000-0000-0000-000000000002');
insert into athletes(id,first_name,last_name,grade) values ('20000000-0000-0000-0000-000000000001','No','Account','10'),('20000000-0000-0000-0000-000000000002','Excluded','Athlete','11');
insert into team_athletes(team_id,athlete_id,squad) select '10000000-0000-0000-0000-000000000001',id,'Novice' from athletes;
set role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',false);
select create_team_season('10000000-0000-0000-0000-000000000001','2026/2027','2026-07-01','2027-06-30',null,array['20000000-0000-0000-0000-000000000001'::uuid],false) as old_id \gset
select pg_temp.assert((select count(*)=2 from team_athletes where status='active'),'draft isolation');
select pg_temp.assert((select count(*)=1 and bool_and(not has_account) and bool_and(squad is null) from team_season_athletes),'account optional and explicit selection');
select pg_temp.assert(create_team_season('10000000-0000-0000-0000-000000000001','2026/2027','2026-07-01','2027-06-30',null,array['20000000-0000-0000-0000-000000000001'::uuid],false)= :'old_id'::uuid,'retry stable');
-- Preparing a first draft must not turn off the still-legacy operational workflow.
update team_athletes set status='active' where athlete_id='20000000-0000-0000-0000-000000000002';
insert into daily_workout_assignments(team_id,workout_date,completed) values ('10000000-0000-0000-0000-000000000001','2026-08-01',true);
insert into daily_workout_assignments(team_id,workout_date,completed) values ('10000000-0000-0000-0000-000000000001','2020-01-01',false);
do $$ begin perform activate_team_season((select id from team_seasons where name='2026/2027')); raise exception 'expected legacy pending guard'; exception when check_violation then null; end $$;
update daily_workout_assignments set completed=true;
select activate_team_season(:'old_id');
select pg_temp.assert((select count(*)=1 from team_athletes where status='active'),'activation excludes omitted athletes');
update team_athletes set squad='Varsity',performance_tier='pool' where status='active';
select pg_temp.assert((select squad='Varsity' and performance_tier='pool' from team_season_athletes where season_id=:'old_id'),'operational squad and tier updates synchronize snapshots');
do $$ begin update daily_workout_assignments set user_id='00000000-0000-0000-0000-000000000099' where team_id='10000000-0000-0000-0000-000000000001'; raise exception 'expected user recipient change guard'; exception when check_violation then null; end $$;
select create_team_season('10000000-0000-0000-0000-000000000001','2027/2028','2027-07-01','2028-06-30',:'old_id',array['20000000-0000-0000-0000-000000000001'::uuid],true) as next_id \gset
reset role;
update athletes set first_name='Changed',grade='12' where first_name='No';
select pg_temp.assert((select first_name='Changed' from team_season_athletes where season_id=:'old_id'),'active name sync');
select pg_temp.assert((select first_name='No' from team_season_athletes where season_id=:'next_id'),'draft snapshot isolation');
insert into daily_workout_assignments(team_id,workout_date,completed) values ('10000000-0000-0000-0000-000000000001','2027-01-01',false);
set role authenticated;
do $$ begin perform archive_team_season((select id from team_seasons where name='2026/2027')); raise exception 'expected archive pending guard'; exception when check_violation then null; end $$;
do $$ begin perform activate_team_season((select id from team_seasons where name='2027/2028')); raise exception 'expected pending guard'; exception when check_violation then null; end $$;
reset role;
update daily_workout_assignments set completed=true;
set role authenticated;
select activate_team_season(:'next_id');
reset role;
update athletes set first_name='Later';
select pg_temp.assert((select first_name='Changed' and grade='12' from team_season_athletes where season_id=:'old_id'),'archived identity stable');
set role authenticated;
select archive_team_season(:'next_id');
select archive_team_season(:'next_id');
select pg_temp.assert((select count(*)=0 from team_athletes where status='active'),'archive eligibility');
do $$ begin update daily_workout_assignments set completed=false where completed is true; raise exception 'expected archived reopening denied'; exception when check_violation then null; end $$;
do $$ begin update daily_workout_assignments set completed=null where completed is true; raise exception 'expected archived null reopening denied'; exception when check_violation then null; end $$;
update daily_workout_assignments set completed=true;
select pg_temp.assert((select bool_and(completed) from daily_workout_assignments),'completed corrections remain allowed after archive');
do $$ begin perform create_team_season('10000000-0000-0000-0000-000000000001','invalid','2028-01-01','2027-01-01',null,'{}',false); raise exception 'expected invalid dates'; exception when check_violation then null; end $$;
do $$ begin perform create_team_season('10000000-0000-0000-0000-000000000001','bad ids','2028-01-01','2029-01-01',null,array['20000000-0000-0000-0000-000000000001'::uuid,'20000000-0000-0000-0000-000000000001'::uuid],false); raise exception 'expected duplicate'; exception when check_violation then null; end $$;
do $$ begin perform create_team_season('10000000-0000-0000-0000-000000000002','foreign','2028-01-01','2029-01-01',null,'{}',false); raise exception 'expected forbidden'; exception when insufficient_privilege then null; end $$;
do $$ begin perform create_team_season('10000000-0000-0000-0000-000000000001','foreign athlete','2030-01-01','2031-01-01',null,array['29999999-0000-0000-0000-000000000001'::uuid],false); raise exception 'expected invalid ID'; exception when check_violation then null; end $$;
do $$ begin update team_athletes set status='active'; raise exception 'expected archived eligibility guard'; exception when check_violation then null; end $$;
do $$ begin insert into daily_workout_assignments(team_id,workout_date) values('10000000-0000-0000-0000-000000000001','2028-01-01'); raise exception 'expected assignment guard'; exception when check_violation then null; end $$;
do $$ begin perform create_team_season('10000000-0000-0000-0000-000000000001','2026/2027','2026-07-01','2027-06-30',null,'{}',false); raise exception 'expected changed retry denial'; exception when check_violation then null; end $$;
do $$ begin perform set_team_season_squad((select id from team_seasons where name='2026/2027'),'20000000-0000-0000-0000-000000000001','Changed'); raise exception 'expected archived placement denial'; exception when check_violation then null; end $$;
reset role;
do $$ begin delete from athletes where id='20000000-0000-0000-0000-000000000001'; raise exception 'expected historical identity protection'; exception when foreign_key_violation then null; end $$;
insert into team_members values('10000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000003','coxswain'),('10000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000004','member');
set role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000003',false);
select pg_temp.assert((select count(*)=2 from team_seasons),'coxswain historical reads');
do $$ begin perform archive_team_season((select id from team_seasons limit 1)); raise exception 'expected coach capability'; exception when insufficient_privilege then null; end $$;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000004',false);
select pg_temp.assert((select count(*)=0 from team_season_athletes),'member cannot read historical snapshots');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000002',false);
select pg_temp.assert((select count(*)=0 from team_seasons),'cross team season RLS');
select pg_temp.assert((select count(*)=0 from team_season_athletes),'cross team snapshot RLS');
do $$ begin update team_seasons set status='active'; raise exception 'expected direct write denied'; exception when insufficient_privilege then null; end $$;
reset role;
select 'team seasons regression assertions passed' as result;
